"use client"
import { useState } from "react"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { Input } from "@atlas/ui-web/primitives/Input/Input"
import { Label } from "@atlas/ui-web/primitives/Label/Label"
import { Switch } from "@atlas/ui-web/primitives/Switch/Switch"
import { Card, CardContent } from "@atlas/ui-web/compositions/Card/Card"
import { mockSubmit } from "../../_shared/mockApi"
import { ERROR_MESSAGES, ORDER_TOTAL, type FailureKind, type PaymentStepProps } from "../schema"

type Errors = { card?: string; expiry?: string; cvc?: string }

const digits = (v: string) => v.replace(/\D/g, "")
const formatCard = (v: string) => digits(v).slice(0, 16).replace(/(.{4})(?=.)/g, "$1 ")
const formatExpiry = (v: string) => {
  const d = digits(v).slice(0, 4)
  return d.length > 2 ? `${d.slice(0, 2)}/${d.slice(2)}` : d
}

function validate(card: string, expiry: string, cvc: string): Errors {
  const errors: Errors = {}
  if (digits(card).length !== 16) errors.card = "Enter the 16-digit card number."
  const month = Number(expiry.slice(0, 2))
  if (!/^\d{2}\/\d{2}$/.test(expiry) || month < 1 || month > 12) errors.expiry = "Enter a valid date as MM/YY."
  if (!/^\d{3,4}$/.test(cvc)) errors.cvc = "Enter the 3 or 4-digit code."
  return errors
}

export function Payment({ data, patch, next }: PaymentStepProps) {
  const [busy, setBusy] = useState(false)
  const [errors, setErrors] = useState<Errors>({})

  const submit = async (e: React.FormEvent) => {
    e.preventDefault()
    const found = validate(data.card, data.expiry, data.cvc)
    setErrors(found)
    if (Object.keys(found).length) return
    const failure: FailureKind = data.simulateTimeout ? "timeout" : "declined"
    setBusy(true)
    try {
      await mockSubmit(data, {
        delayMs: failure === "timeout" ? 2500 : 1500,
        failRate: 1,
        errorMessage: ERROR_MESSAGES[failure],
      })
    } catch {
      patch({ failure, attempts: data.attempts + 1 })
      next()
    } finally {
      setBusy(false)
    }
  }

  return (
    <form
      onSubmit={submit}
      noValidate
      style={{
        display: "flex",
        flexDirection: "column",
        gap: "var(--atlas-spacing-5)",
        paddingInline: "var(--atlas-spacing-4)",
        paddingBlock: "var(--atlas-spacing-4)",
        color: "var(--atlas-foreground)",
        fontFamily: "var(--atlas-font-sans)",
      }}
    >
      <h1 style={{ margin: 0, fontSize: "var(--atlas-text-h2)", fontWeight: "var(--atlas-font-weight-semibold)" }}>
        Payment
      </h1>

      <Card variant="filled" size="md">
        <CardContent>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline" }}>
            <span style={{ color: "var(--atlas-foreground-muted)", fontSize: "var(--atlas-font-size-sm)" }}>Order total</span>
            <span style={{ fontSize: "var(--atlas-text-h3)", fontWeight: "var(--atlas-font-weight-semibold)" }}>
              {ORDER_TOTAL}
            </span>
          </div>
        </CardContent>
      </Card>

      <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-1_5)" }}>
        <Label htmlFor="pe-card" required invalid={!!errors.card}>Card number</Label>
        <Input
          id="pe-card"
          size="lg"
          inputMode="numeric"
          autoComplete="cc-number"
          placeholder="1234 5678 9012 3456"
          value={data.card}
          invalid={!!errors.card}
          aria-describedby={errors.card ? "pe-card-err" : undefined}
          disabled={busy}
          onChange={(e) => patch({ card: formatCard(e.target.value) })}
        />
        {errors.card && <FieldError id="pe-card-err">{errors.card}</FieldError>}
      </div>

      <div style={{ display: "flex", gap: "var(--atlas-spacing-3)" }}>
        <div style={{ flex: 1, display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-1_5)" }}>
          <Label htmlFor="pe-expiry" required invalid={!!errors.expiry}>Expiry</Label>
          <Input
            id="pe-expiry"
            size="lg"
            inputMode="numeric"
            autoComplete="cc-exp"
            placeholder="MM/YY"
            value={data.expiry}
            invalid={!!errors.expiry}
            aria-describedby={errors.expiry ? "pe-expiry-err" : undefined}
            disabled={busy}
            onChange={(e) => patch({ expiry: formatExpiry(e.target.value) })}
          />
          {errors.expiry && <FieldError id="pe-expiry-err">{errors.expiry}</FieldError>}
        </div>
        <div style={{ flex: 1, display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-1_5)" }}>
          <Label htmlFor="pe-cvc" required invalid={!!errors.cvc}>CVC</Label>
          <Input
            id="pe-cvc"
            size="lg"
            inputMode="numeric"
            autoComplete="cc-csc"
            placeholder="123"
            value={data.cvc}
            invalid={!!errors.cvc}
            aria-describedby={errors.cvc ? "pe-cvc-err" : undefined}
            disabled={busy}
            onChange={(e) => patch({ cvc: digits(e.target.value).slice(0, 4) })}
          />
          {errors.cvc && <FieldError id="pe-cvc-err">{errors.cvc}</FieldError>}
        </div>
      </div>

      <Button type="submit" variant="primary" size="lg" loading={busy} style={{ width: "100%" }}>
        Pay now · {ORDER_TOTAL}
      </Button>

      <Switch
        size="sm"
        label="Simulate network timeout"
        description="Prototype control: fail with a timeout instead of a card decline"
        checked={data.simulateTimeout}
        disabled={busy}
        onCheckedChange={(simulateTimeout) => patch({ simulateTimeout })}
      />
    </form>
  )
}

function FieldError({ id, children }: { id: string; children: React.ReactNode }) {
  return (
    <span id={id} role="alert" style={{ color: "var(--atlas-danger)", fontSize: "var(--atlas-font-size-sm)" }}>
      {children}
    </span>
  )
}

