"use client"
import { useState } from "react"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { Alert } from "@atlas/ui-web/compositions/Alert/Alert"
import { mockSubmit } from "../../_shared/mockApi"
import { ERROR_MESSAGES, ORDER_TOTAL, type FailureKind, type PaymentStepProps } from "../schema"

const COPY: Record<FailureKind, { title: string; description: string }> = {
  declined: {
    title: "Your card was declined",
    description:
      "Your bank didn't approve this payment. Check the card details you entered, or use a different card.",
  },
  timeout: {
    title: "The payment timed out",
    description:
      "We didn't get a response from your bank, so we can't confirm the payment went through. Check your connection, then try again.",
  },
}

export function Failure({ data, patch, back, goTo }: PaymentStepProps) {
  const [busy, setBusy] = useState(false)
  const [supportOpen, setSupportOpen] = useState(false)
